package com.cestasdamel.erp.controller; import com.cestasdamel.erp.dto.Requests.*; import com.cestasdamel.erp.dto.Responses.Auth; import com.cestasdamel.erp.service.AuthService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/auth") @RequiredArgsConstructor public class AuthController {private final AuthService service; @PostMapping("/register") ResponseEntity<Auth> register(@Valid @RequestBody Register r){return ResponseEntity.status(HttpStatus.CREATED).body(service.register(r));}@PostMapping("/login") Auth login(@Valid @RequestBody Login r){return service.login(r);}}
